using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Preserve EF Core 8 id format ("Product|<key>") so existing 500K documents remain readable.
        optionsBuilder.UseCosmos(o =>
        {
            // If connection is configured elsewhere, keep this option flag.
        });
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // Restore EF8 property name so existing documents and direct SQL queries keep working.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change #2: id values changed from "EntityType|Key" to just "Key".
        // Restore EF8 format so the 500K existing documents are still addressable.
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Id);
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

        modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

