using Microsoft.EntityFrameworkCore;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasIndex(p => p.Sku);

            // ── Breaking change #1: Discriminator renamed from "Discriminator" to "$type" ──
            // Existing 500K documents and direct SQL queries use c.Discriminator.
            // Restore the EF8 property name.
            b.HasDiscriminator<string>("Discriminator");

            // ── Breaking change #2: id format changed from "Product|<key>" to "<key>" ──
            // Existing documents store id as "Product|123". Map the explicit CosmosId
            // property to the JSON "id" field so EF Core 9 can read and write them.
            b.HasKey(p => p.CosmosId);
            b.Property(p => p.CosmosId).ToJsonProperty("id");
            b.Property(p => p.Id).ToJsonProperty("Id");
        });
    }
}

class Product
{
    // Cosmos "id" — existing docs use format "Product|<Id>", e.g. "Product|123"
    public string CosmosId { get; set; } = null!;
    public int Id { get; set; }
    public string Sku { get; set; } = null!;
}

